{
  "schema_version": 1,
  "verdict": "needs-correction",
  "finding_class": "cue-content",
  "rationale": "Both forms can express disgust, but Malaysian Malay geli is highly polysemous and commonly means ticklish or amused, so the missing false-friend contrast creates learner risk. The different-common-word relation is also too strong without usage evidence because Malay jijik is itself a direct disgust term and geli is not exclusive to Malaysian Malay.",
  "claim_reviews": [
    {
      "subject": "Indonesian answer: jijik",
      "conclusion": "Correct for disgusted/disgusting aversion caused by something dirty, vile, or unpleasant.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/jijik.html"
      ]
    },
    {
      "subject": "Malaysian Malay answer: geli",
      "conclusion": "Valid for disgust or revulsion, but also commonly means ticklish, amused, or physically uncomfortable.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=169476&keyword=geli"
      ]
    },
    {
      "subject": "English cue and sense",
      "conclusion": "The cue disgusted and the sense of strong aversion toward something unpleasant are broadly aligned, though geli may require contextual disambiguation.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=169476&keyword=geli",
        "https://kbbi.web.id/jijik.html"
      ]
    },
    {
      "subject": "Final relation: different-common-word",
      "conclusion": "Not sufficiently supported as a clean variety contrast: Malay also has jijik for disgust, while geli is not uniquely Malaysian.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=123312&keyword=jijik",
        "https://prpm.dbp.gov.my/Cari1?d=169476&keyword=geli"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "A learner-critical contrast is missing: Malaysian Malay geli can mean ticklish or amused, not only disgusted.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=169476&keyword=geli"
      ]
    }
  ]
}
